import{S as t,o as d,c as a,a9 as c,B as i}from"./chunks/framework.IJ8axLs_.js";const n="/agentsrc/images/deepseek/05-seam-triple.svg",r="/agentsrc/images/deepseek/05-execution-world.svg",l="/agentsrc/images/deepseek/05-tool-pipeline.svg",b=JSON.parse('{"title":"capability 缝与执行世界：换一个实现，动整套产品","description":"","frontmatter":{"title":"capability 缝与执行世界：换一个实现，动整套产品"},"headers":[],"relativePath":"deepseek/05-capability-seams.md","filePath":"deepseek/05-capability-seams.md","lastUpdated":1790217011000}'),p={name:"deepseek/05-capability-seams.md"},m=Object.assign(p,{setup(h){const o=[{question:"按 `dsh` 的定义，一个能力最少要设计哪三种角色？",options:["接口、实现、消费方","接口、实现、配置","工具、沙箱、审批","接口、事件、日志"],correct:0,explanation:"capability 缝 = Service Definition + Provider + Consumer，缺一不算 seam。B 用配置顶替消费方，C 是具体能力名，D 是机制要素不是角色划分。"},{question:"接口包（Service Definition）为什么不能 import 任何实现包？",options:["为了减少包的安装体积","因为实现包不许被别人引用","换实现时消费方也得跟着改","为了让编译速度更快"],correct:2,explanation:"接口一旦绑死实现，Consumer 就跟着焊死；接口独立成包，Provider 随便换、消费方与整棵树不动。A/B/D 都不是这条依赖规则的理由。"},{question:"单调守卫（ToolGuard）的返回类型刻意没有 allow 分支，目的是？",options:["让守卫更短更容易写","后续监听者无法把拒绝翻回放行","减少一次类型判断的开销","让审批流程接管允许权"],correct:1,explanation:"返回 undefined 维持原判、返回理由只会收紧：裁决只紧不松，防止监听者之间互相翻案。A/C 与设计意图无关，D 说的是 approval 的位置而非守卫。"},{question:"一次工具调用带 `danger-full-access` 模式，实际会发生什么？",options:["沙箱以最宽规则包住进程","调用被拒绝并要求审批","沙箱后端切换到全量模式","绕过沙箱，直接执行原命令"],correct:3,explanation:'danger-full-access 是旁路：消费方直接 spawn 原 argv，根本不调 ctx.sandbox。A/C 把旁路误读成最宽围栏，B 混淆了"请求放宽一档"的人工审批路径。'},{question:'"换一个 provider 会带着 bash、PTY、LSP 整套搬家"的根本原因是？',options:["这些工具写在同一个包里","配置文件强制绑定它们的行","它们共享同一个执行世界","它们的接口签名完全相同"],correct:2,explanation:"fs 与 subprocess 共享一个执行世界，bash/PTY/LSP 都经 ctx.subprocess 这条缝去 spawn；把世界指向远程，ssh 三件套（fs-ssh/subprocess-ssh/sandbox-ssh）一起换，所有消费者自动迁移。A/C/D 都不是机制本身。"}];return(u,e)=>{const s=t("Quiz");return d(),a("div",null,[e[0]||(e[0]=c("",50)),i(s,{questions:o})])}}});export{b as __pageData,m as default};
